33	abstract class CodeGenerator<T extends DatabaseConnection["type"]> {
34	  protected connection: Extract<DatabaseConnection, { type: T }>;
35	  protected orm: ConnectionLibrary;
36	  protected secrets: SecretContainer;
37	
38	  constructor(
39	    connection: Extract<DatabaseConnection, { type: T }>,
40	    orm: ConnectionLibrary,
41	    secrets: SecretContainer,
42	  ) {
43	    this.connection = connection;
44	    this.orm = orm;
45	    this.secrets = secrets;
46	  }
47	
48	  get imports(): Set<string> {
49	    const imports = new Set<string>(this.generateImports());
50	    switch (this.orm) {
51	      case "sqlalchemy":
52	        imports.add("import sqlalchemy");
53	        break;
54	      case "sqlmodel":
55	        imports.add("import sqlmodel");
56	        break;
57	      case "duckdb":
58	        imports.add("import duckdb");
59	        break;
60	      case "ibis":
61	        imports.add("import ibis");
62	        break;
63	    }
64	    return imports;
65	  }
66	
67	  protected abstract generateImports(): string[];
68	
69	  abstract generateConnectionCode(): string;
70	}
