72	const makePrivate = (name: string) => `_${name}`;
73	
74	class SecretContainer {
75	  private secrets: Record<string, string> = {};
76	
77	  get imports(): Set<string> {
78	    if (Object.keys(this.secrets).length === 0) {
79	      return new Set<string>();
80	    }
81	    return new Set<string>(["import os"]);
82	  }
83	
84	  print(
85	    varName: string,
86	    secretKeyOrValue: string | number | boolean,
87	    defaultValue?: string | undefined,
88	  ): string {
89	    varName = makePrivate(varName);
90	    if (isSecret(secretKeyOrValue)) {
91	      const withoutPrefix = unprefixSecret(secretKeyOrValue);
92	      const secretGetter = defaultValue
93	        ? `os.environ.get("${withoutPrefix}", "${defaultValue}")`
94	        : `os.environ.get("${withoutPrefix}")`;
95	      this.secrets[varName] = secretGetter;
96	      return varName;
97	    }
98	    if (defaultValue != null) {
99	      const secretGetter = `os.environ.get("${secretKeyOrValue}", "${defaultValue}")`;
100	      this.secrets[varName] = secretGetter;
101	      return varName;
102	    }
103	
104	    if (typeof secretKeyOrValue === "number") {
105	      return `${secretKeyOrValue}`;
106	    }
107	    // If its a number, return it as is
108	    if (typeof secretKeyOrValue === "number") {
109	      return `${secretKeyOrValue}`;
110	    }
111	    if (typeof secretKeyOrValue === "boolean") {
112	      return formatBoolean(secretKeyOrValue);
113	    }
114	    if (!secretKeyOrValue) {
115	      return "";
116	    }
117	
118	    return `"${secretKeyOrValue}"`;
119	  }
120	
121	  printInFString(
122	    varName: string,
123	    secretKeyOrValue: string | number | undefined | boolean,
124	    defaultValue?: string | undefined,
125	  ): string {
126	    if (secretKeyOrValue === undefined) {
127	      return "";
128	    }
129	    // If its a number, return it as is
130	    if (typeof secretKeyOrValue === "number") {
131	      return `${secretKeyOrValue}`;
132	    }
133	    if (typeof secretKeyOrValue === "boolean") {
134	      return formatBoolean(secretKeyOrValue);
135	    }
136	
137	    const value = this.print(varName, secretKeyOrValue, defaultValue);
138	    // If its a string, remove the quotes
139	    if (value.startsWith('"') && value.endsWith('"')) {
140	      return value.slice(1, -1);
141	    }
142	    // If its a variable, wrap it in curly braces
143	    return `{${value}}`;
144	  }
145	
146	  /**
147	   * Generate a password variable for connection strings, supporting inline values,
148	   * environment variable lookups, and f-string formatting.
149	   * @param {string|undefined} password - Fallback password value.
150	   * @param {string} passwordPlaceholder - Environment variable name.
151	   * @param {boolean} inFString - If true, wrap for Python f-string.
152	   * @param {string} [variableName] - Variable name (default: "password").
153	   * @returns {string}
154	   *
155	   * @example
156	   * `printPassword("token123", "DATABRICKS_ACCESS_TOKEN", true, "access_token")`
157	   *
158	   * Returns:
159	   * ```python
160	   * _access_token = os.environ.get("DATABRICKS_ACCESS_TOKEN", "token123")
161	   * f"db://sample:{_access_token}@sample.com"
162	   * ```
163	   *
164	   * @example
165	   * `printPassword("token123", "DATABRICKS_ACCESS_TOKEN", false, "access_token")`
166	   *
167	   * Returns:
168	   * ```python
169	   * access_token = os.environ.get("DATABRICKS_ACCESS_TOKEN", "token123")
170	   * f"db://sample:access_token@sample.com"
171	   * ```
172	   */
173	  printPassword(
174	    password: string | undefined,
175	    passwordPlaceholder: string,
176	    inFString: boolean,
177	    variableName?: string,
178	  ): string {
179	    // Inline passwords should use printInFString, otherwise use print
180	    const printMethod = inFString
181	      ? this.printInFString.bind(this)
182	      : this.print.bind(this);
183	
184	    return isSecret(password)
185	      ? printMethod(variableName || "password", password)
186	      : printMethod(variableName || "password", passwordPlaceholder, password);
187	  }
188	
189	  getSecrets(): Record<string, string> {
190	    return this.secrets;
191	  }
192	
193	  formatSecrets(): string {
194	    if (Object.keys(this.secrets).length === 0) {
195	      return "";
196	    }
197	
198	    return Object.entries(this.secrets)
199	      .map(([k, v]) => `${k} = ${v}`)
200	      .join("\n");
201	  }
202	}
