210	    const ssl = this.connection.ssl
211	      ? ", connect_args={'sslmode': 'require'}"
212	      : "";
213	    const password = this.secrets.printPassword(
214	      this.connection.password,
215	      "POSTGRES_PASSWORD",
216	      true,
217	    );
218	    const username = this.secrets.printInFString(
219	      "username",
220	      this.connection.username,
221	    );
222	    const host = this.secrets.printInFString("host", this.connection.host);
223	    const port = this.secrets.printInFString("port", this.connection.port);
224	    const database = this.secrets.printInFString(
225	      "database",
226	      this.connection.database,
227	    );
228	
229	    return dedent(`
230	      DATABASE_URL = f"postgresql://${username}:${password}@${host}:${port}/${database}"
231	      engine = ${this.orm}.create_engine(DATABASE_URL${ssl})
232	    `);
233	  }
234	}
