    const connection = this.connection;
    const authType = connection.authType;

    // Collect every value that may be rendered, keyed by the Python variable
    // name it would be assigned to. We invoke the renderers in alphabetical
    // order of the variable name so that any generated environment-variable
    // declarations (e.g. `_account = os.environ.get(...)`) appear alphabetically.
    const fields: Array<{ key: string; render: () => string }> = [];
    const add = (key: string, render: () => string) =>
      fields.push({ key, render });

    add("account", () => this.secrets.print("account", connection.account));
    add("database", () => this.secrets.print("database", connection.database));
    if (connection.warehouse) {
      const warehouse = connection.warehouse;
      add("warehouse", () => this.secrets.print("warehouse", warehouse));
    }
    if (connection.schema) {
      const schema = connection.schema;
      add("schema", () => this.secrets.print("schema", schema));
    }
    if (connection.role) {
      const role = connection.role;
      add("role", () => this.secrets.print("role", role));
    }

    switch (authType.type) {
      case "Password":
        add("user", () => this.secrets.print("user", authType.username));
        add("password", () =>
          this.secrets.printPassword(
            authType.password,
            "SNOWFLAKE_PASSWORD",
            false,
          ),
        );
        break;
      case "SSO (Browser)":
        add("user", () => this.secrets.print("user", authType.username));
        break;
      case "Key Pair":
        add("user", () => this.secrets.print("user", authType.username));
        add("private_key_file", () =>
          this.secrets.print("private_key_file", authType.private_key_path),
        );
        if (authType.private_key_passphrase) {
          add("private_key_file_pwd", () =>
            this.secrets.printPassword(
              authType.private_key_passphrase,
              "SNOWFLAKE_PRIVATE_KEY_PASSPHRASE",
              false,
              "private_key_file_pwd",
            ),
          );
        }
        break;
      case "OAuth / PAT":
        add("token", () =>
          this.secrets.printPassword(
            authType.token,
            "SNOWFLAKE_TOKEN",
            false,
            "token",
          ),
        );
        break;
      default:
        assertNever(authType);
    }

    // Render in alphabetical order so secret declarations are alphabetical.
    const rendered: Record<string, string> = {};
    [...fields]
      .sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0))
      .forEach(({ key, render }) => {
        rendered[key] = render();
      });

    // Common URL params, in the required order.
    const params: Record<string, string | undefined> = {
      account: rendered.account,
      database: rendered.database,
      warehouse: rendered.warehouse,
      schema: rendered.schema,
      role: rendered.role,
    };

    // Auth-specific URL params and connect_args.
    let connectArgs = "";
    switch (authType.type) {
      case "Password":
        params.user = rendered.user;
        params.password = rendered.password;
        if (authType.enable_mfa) {
          connectArgs = `,\n        connect_args={"authenticator": "username_password_mfa"}`;
        }
        break;
      case "SSO (Browser)":
        params.user = rendered.user;
        params.authenticator = '"externalbrowser"';
        break;
      case "Key Pair": {
        params.user = rendered.user;
        const connectArgsDict: Record<string, string | undefined> = {
          authenticator: '"SNOWFLAKE_JWT"',
          private_key_file: rendered.private_key_file,
          private_key_file_pwd: rendered.private_key_file_pwd,
        };
        connectArgs = `,\n        connect_args={\n${formatDictionaryEntries(
          connectArgsDict,
          (inner) => `          ${inner}`,
        )},\n        }`;
        break;
      }
      case "OAuth / PAT":
        params.authenticator = '"oauth"';
        params.token = rendered.token;
        break;
      default:
        assertNever(authType);
    }

    return dedent(`
      engine = ${this.orm}.create_engine(
        URL(
${formatUrlParams(params, (inner) => `          ${inner}`)},
        )${connectArgs}
      )
    `);
  }
